import type { DaemonPolicyValues } from "@symnav/daemon";
import type { DaemonClock } from "./daemon-clock.js";

export class DaemonLifetime {
  private timer: ReturnType<typeof setTimeout> | undefined;
  private deadline: number;
  private navigationActive = false;
  private stopped = false;
  private idleTriggered = false;

  constructor(
    private readonly clock: Pick<DaemonClock, "wallNowMs">,
    policy: Pick<DaemonPolicyValues["shutdown"], "idleTimeoutMs">,
    private readonly onIdle: () => Promise<void>,
  ) {
    this.idleTimeoutMs = policy.idleTimeoutMs;
    this.deadline = this.clock.wallNowMs() + this.idleTimeoutMs;
    this.schedule();
  }

  private readonly idleTimeoutMs: number;

  navigationAccepted(): void {
    if (this.stopped) return;
    this.navigationActive = true;
    this.deadline = this.clock.wallNowMs() + this.idleTimeoutMs;
    this.schedule();
  }

  queueBecameIdle(): void {
    if (this.stopped) return;
    this.navigationActive = false;
    if (this.clock.wallNowMs() >= this.deadline) this.triggerIdle();
  }

  stop(): void {
    this.stopped = true;
    if (this.timer !== undefined) clearTimeout(this.timer);
    this.timer = undefined;
  }

  private schedule(): void {
    if (this.timer !== undefined) clearTimeout(this.timer);
    const remainingMs = Math.max(0, this.deadline - this.clock.wallNowMs());
    this.timer = setTimeout(() => this.deadlineReached(), remainingMs);
    this.timer.unref?.();
  }

  private deadlineReached(): void {
    this.timer = undefined;
    if (this.stopped || this.navigationActive) return;
    this.triggerIdle();
  }

  private triggerIdle(): void {
    if (this.idleTriggered) return;
    this.idleTriggered = true;
    void this.onIdle();
  }
}

import { performance } from "node:perf_hooks";

export interface DaemonClock {
  wallNowMs(): number;
  monotonicNowMs(): number;
}

interface DaemonClockSources {
  readonly wallNowMs: () => number;
  readonly monotonicNowMs: () => number;
}

export class NodeDaemonClock implements DaemonClock {
  constructor(
    private readonly sources: DaemonClockSources = {
      wallNowMs: Date.now,
      monotonicNowMs: () => performance.now(),
    },
  ) {}

  wallNowMs(): number {
    return this.sources.wallNowMs();
  }

  monotonicNowMs(): number {
    return this.sources.monotonicNowMs();
  }
}

import { DaemonPolicy } from "@symnav/daemon";
import { DaemonPolicyTestFactory } from "../../test/helpers/daemon-policy.js";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { DaemonClock } from "./daemon-clock.js";
import { DaemonLifetime } from "./daemon-lifetime.js";

const IDLE_TIMEOUT_MS = DaemonPolicy.currentSystem().values.shutdown.idleTimeoutMs;

describe("DaemonLifetime", () => {
  beforeEach(() => vi.useFakeTimers());
  afterEach(() => vi.useRealTimers());

  it("resets its idle deadline only for navigation", async () => {
    let now = 0;
    const clock: Pick<DaemonClock, "wallNowMs"> = { wallNowMs: () => now };
    const onIdle = vi.fn(async () => undefined);
    const lifetime = new DaemonLifetime(clock, idlePolicy(IDLE_TIMEOUT_MS), onIdle);

    now = IDLE_TIMEOUT_MS - 1;
    vi.advanceTimersByTime(IDLE_TIMEOUT_MS - 1);
    lifetime.navigationAccepted();
    lifetime.queueBecameIdle();
    now += IDLE_TIMEOUT_MS - 1;
    await vi.advanceTimersByTimeAsync(IDLE_TIMEOUT_MS - 1);
    expect(onIdle).not.toHaveBeenCalled();

    now += 1;
    await vi.advanceTimersByTimeAsync(1);
    expect(onIdle).toHaveBeenCalledOnce();
  });

  it("waits for active navigation to finish after deadline", async () => {
    let now = 0;
    const onIdle = vi.fn(async () => undefined);
    const lifetime = new DaemonLifetime({ wallNowMs: () => now }, idlePolicy(10), onIdle);
    lifetime.navigationAccepted();

    now = 10;
    await vi.advanceTimersByTimeAsync(10);
    expect(onIdle).not.toHaveBeenCalled();
    lifetime.queueBecameIdle();
    await Promise.resolve();
    expect(onIdle).toHaveBeenCalledOnce();
  });

  it("keeps the constructor-started acceptance deadline after completion", async () => {
    let now = 0;
    const onIdle = vi.fn(async () => undefined);
    const lifetime = new DaemonLifetime({ wallNowMs: () => now }, idlePolicy(10), onIdle);

    now = 8;
    vi.advanceTimersByTime(8);
    lifetime.navigationAccepted();
    now = 18;
    await vi.advanceTimersByTimeAsync(10);
    expect(onIdle).not.toHaveBeenCalled();

    lifetime.queueBecameIdle();
    await Promise.resolve();

    expect(onIdle).toHaveBeenCalledOnce();
  });

  it("stops its timer permanently", async () => {
    let now = 0;
    const onIdle = vi.fn(async () => undefined);
    const lifetime = new DaemonLifetime({ wallNowMs: () => now }, idlePolicy(10), onIdle);
    lifetime.stop();
    now = 20;
    await vi.advanceTimersByTimeAsync(20);
    expect(onIdle).not.toHaveBeenCalled();
  });
});

function idlePolicy(idleTimeoutMs: number) {
  return DaemonPolicyTestFactory.withOverrides(DaemonPolicy.currentSystem(), {
    shutdown: { idleTimeoutMs },
  }).values.shutdown;
}

